import java.util.List;

/**
 * A bulk grade as the screen sends it: the ids of the selected people, the grade (A, B or C) and
 * the date it is from (yyyy-MM-dd; blank for the sheet's today).
 */
public record BulkGradeRequest(List<String> personIds, String grade, String gradeFrom) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date given, or the sheet's today when none is. */
public class RetirePerson {
    public void retire(@Val RetireInput input, @Val Sheet sheet, @Val Person person,
            PersonRepository repository) {
        person.setRetiredFrom(input.from() != null ? input.from() : sheet.today());
        repository.saveRetired(person);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated retirement: the date the person is retired from (null: the sheet's today). */
public record RetireInput(LocalDate from) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the retirement. Runs after it is saved. */
public class AuditPersonRetired {
    public void audit(@Val Sheet sheet, @Val Person person,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("personId") String personId, @Val Sheet sheet,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Person person = null;
        try {
            person = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { GRADES } from '../people/people';
import type { Grade } from '../people/people';
import { clearRowError } from '../people/rowError';
import { useUser } from '../session/session';
import { clearSelectedPeople, selectPerson, useSelectedPeople } from './selection';

function SelectHead() {
  return <th>Select</th>;
}

// A tick on each person's row, picking them for the bulk grade.
function PersonSelect({ sheetId, person }: { sheetId: string; person: Person }) {
  const selected = useSelectedPeople(sheetId);
  return (
    <td>
      <input
        type="checkbox"
        data-testid="person-select"
        checked={selected.has(person.id)}
        onChange={(e) => selectPerson(sheetId, person.id, e.target.checked)}
      />
    </td>
  );
}

// Gives the ticked people a grade together, from a from-date ('' for the sheet's today). The server
// grades each in list order exactly as the person form would; the bar shows how many were graded.
// The count is cleared while it runs. A refusal shows the error and changes nothing.
function BulkGrade({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const selected = useSelectedPeople(sheetId);
  const [user] = useUser();
  const [grade, setGrade] = useState<Grade>('A');
  const [gradeFrom, setGradeFrom] = useState('');
  const [graded, setGraded] = useState<number | null>(null);
  const [error, setError] = useState('');

  const once = useOnce();
  const apply = useMutation({
    mutationFn: (personIds: string[]) =>
      postJson<{ graded: number }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/bulk-grade`,
        { personIds, grade, gradeFrom },
        user,
      ),
    onSuccess: (r) => {
      setGraded(r.graded);
      clearSelectedPeople(sheetId);
      void queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onError: () => setError('The selected people could not be given that grade.'),
  });

  const press = () => {
    setGraded(null);
    setError('');
    const ids = [...selected];
    ids.forEach(clearRowError);
    once((done) => apply.mutate(ids, { onSettled: done }));
  };

  return (
    <section data-testid="bulk-people">
      <label>
        Grade{' '}
        <select
          data-testid="bulk-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value as Grade);
            setError('');
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        From{' '}
        <input
          type="date"
          data-testid="bulk-grade-from"
          value={gradeFrom}
          onChange={(e) => {
            setGradeFrom(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="button" data-testid="bulk-grade-apply" onClick={press} disabled={apply.isPending}>
        Grade selected ({selected.size})
      </button>
      {graded !== null && (
        <>
          {' '}Graded <span data-testid="bulk-graded">{graded}</span>
        </>
      )}
      {error && (
        <p role="alert" data-testid="person-error">
          {error}
        </p>
      )}
    </section>
  );
}

export const contributions = [
  SheetBody.fill({ order: 7, Component: BulkGrade }),
  PersonHead.fill({ order: 1, Component: SelectHead }),
  PersonRow.fill({ order: 1, Component: PersonSelect }),
];

